import styled from '@emotion/styled';
import { theme } from 'theme';

export const StyledChipIcon = styled('div')({
  alignItems: 'center',
  color: theme.colors.interfaceLabelPrimary,
  display: 'flex',
  justifyContent: 'center',
  marginLeft: '-4px',
  marginRight: '4px',
  '&>svg': {
    height: '1rem',
    width: '1rem',
  },
});
